137	  /// Log a libghostty startup failure and report it to Sentry. The terminal engine is the app's
138	  /// core feature; when it fails to come up the app degrades to a placeholder rather than crashing
139	  /// (the fail-soft contract above), so the crash handler never sees these — a Sentry event is the
140	  /// only way we'd learn the engine broke in the field. The `os.Logger` line stays for local
141	  /// `log stream`/Console debugging; Sentry gets the same message at `level`.
142	  private func reportStartupFailure(_ message: String, level: SentryLevel = .error) {
143	    logger.error("\(message, privacy: .public)")
144	    SentrySDK.capture(message: message) { scope in scope.setLevel(level) }
145	  }
