147	  /// Point `GHOSTTY_RESOURCES_DIR` at the bundled `ghostty/` tree (terminfo + shell-integration).
148	  /// Returns false (and logs) if the resources are missing — shell integration, the `xterm-ghostty`
149	  /// terminfo entry, and OSC-7 cwd reporting all depend on them. See Resources/ghostty/SOURCE.md.
150	  private func resolveResources() -> Bool {
151	    guard let resourcesURL = GhosttyResources.exportResourcesDir() else {
152	      reportStartupFailure("bundled ghostty resources not found — terminals unavailable")
153	      return false
154	    }
155	
156	    // Resolve the bundled terminfo dir; each surface injects it as `TERMINFO` into the shell's env
157	    // (see `GhosttySurfaceView.createSurface`). libghostty sets `TERM=xterm-ghostty` but builds the
158	    // child environment itself — a plain process `setenv("TERMINFO", …)` does NOT reach the shell —
159	    // and macOS has no system `xterm-ghostty` entry, so without injecting it the shell can't resolve
160	    // the terminal's capabilities (e.g. `kbs`), which breaks line editing (notably Backspace).
161	    // Entries live under hex-named dirs (`terminfo/78/xterm-ghostty`, 0x78 = 'x').
162	    let terminfoURL = resourcesURL.appendingPathComponent("terminfo")
163	    if FileManager.default.fileExists(
164	      atPath: terminfoURL.appendingPathComponent("78/xterm-ghostty").path)
165	    {
166	      terminfoDirectory = terminfoURL.path
167	    } else {
168	      reportStartupFailure(
169	        "bundled xterm-ghostty terminfo missing — terminal line editing may misbehave",
170	        level: .warning)
171	    }
172	    return true
173	  }
