189	  /// Rebuild the config for the current appearance and apply it app-wide (called on a light/dark
190	  /// change from `TerminalSessions.applyThemeToAll`). Individual surfaces are refreshed by the
191	  /// caller via `GhosttySurfaceView.updateConfig`.
192	  ///
193	  /// `force` rebuilds even when the appearance is unchanged — needed for a *same-appearance theme
194	  /// switch* (issue #36), where the active theme name changes but `dark` does not, so the plain
195	  /// appearance guard would skip the rebuild.
196	  func reloadConfig(force: Bool = false) {
197	    guard let app else { return }
198	    let dark = Self.isCurrentAppearanceDark()
199	    // Unchanged appearance and not forced → nothing to rebuild.
200	    guard force || dark != lastConfiguredDark else { return }
201	    lastConfiguredDark = dark
202	    writeThemeConfig(dark: dark)
203	    guard let newConfig = loadConfig() else { return }
204	    ghostty_app_update_config(app, newConfig)
205	    let old = config
206	    config = newConfig
207	    if let old { ghostty_config_free(old) }
208	  }
